/// Draws frames until Code and Spec have slid into place, meeting when
/// both are selected and otherwise either side of the chain, and the
/// chain's icon is as far from what shows of Code as from what shows of
/// Spec: a selected tab's edge, or an unselected tab's label.
fn settle_tabs(
    handle: gpui_kit::AnyWindowHandle,
    code_selected: bool,
    spec_selected: bool,
    cx: &mut TestAppContext,
) -> [Bounds; 5] {
    let joined = code_selected && spec_selected;
    let inset = |selected: bool| {
        if selected {
            super::px(0.)
        } else {
            super::TAB_LABEL_INSET
        }
    };
    let start = std::time::Instant::now();
    loop {
        let layout = cx
            .update_window(handle, |_, window, cx| tab_layout(window, cx))
            .unwrap();
        let [code, chain, spec, _, icon] = layout;
        let before = icon.left() - (code.right() - inset(code_selected));
        let after = spec.left() + inset(spec_selected) - icon.right();
        let spec_offset = spec.left() - if joined { code.right() } else { chain.right() };
        if (before - after).abs() <= super::px(0.5) && spec_offset.abs() <= super::px(0.5) {
            return layout;
        }
        assert!(
            start.elapsed() < TIMEOUT,
            "the tabs did not settle: the icon is {before:?} after Code and {after:?} \
             before Spec, and Spec is {spec_offset:?} out of place"
        );
        std::thread::sleep(Duration::from_millis(16));
    }
}

