        .await;

        let text = editor.read_with(cx, |editor, _| editor.value().to_string());
        assert_eq!(text, "Update @{ApplicationScope}");
        let accepted = chat_input.read_with(cx, |input, _| {
            input.lsp.as_ref().unwrap().accepted_imports()
